from django.db import migrations
from subekashi.lib.url import format_bilibili_url


# ビリビリ動画のURLを「https://bilibili.com/video/BV<id>」に揃える（#1246）
# 揃えたURLが既にある場合（av番号とBV番号で登録されていた同じ動画など）は、曲をそのURLに移して1つにまとめる
def normalize_bilibili_urls(apps, schema_editor):
    SongLink = apps.get_model('subekashi', 'SongLink')
    for link in SongLink.objects.filter(url__icontains='bilibili.com').order_by('id'):
        url = format_bilibili_url(link.url)
        if url == link.url:
            continue

        same_link = SongLink.objects.filter(url=url).first()
        if same_link is None:
            link.url = url
            link.save()
            continue

        same_link.songs.add(*link.songs.all())
        same_link.allow_dup = same_link.allow_dup or link.allow_dup
        # 曲に紐づくURLが「削除された曲のURL」として扱われないよう、両方とも削除された曲のURLのときのみTrueにする
        same_link.is_removed = same_link.is_removed and link.is_removed
        same_link.save()
        link.delete()


class Migration(migrations.Migration):

    dependencies = [
        ('subekashi', '0050_song_category_meme'),
    ]

    operations = [
        migrations.RunPython(normalize_bilibili_urls, migrations.RunPython.noop),
    ]
